import { focus, pxToRem } from "../../helpers";
import { StyleFn } from "..";

export const Stepper: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const { focusWithPseudo } = focus(theme, mode);

  const defaultBrandColor = color.surface.accent.default[mode];
  const defaultBgColor = color.surface.interaction.default[mode];
  const defaultTextColor = color.text.neutral.strong[mode];
  const textColor = color.text.accent.corporate[mode];

  return {
    root: {
      display: "flex",
      margin: 0,
      padding: 0,
      "& > *": {
        flex: 1,
        display: "flex",
      },
    },
    _vertical: {
      flexDirection: "column",
      "& $step": {
        alignItems: "flex-start",
        position: "relative",
        minHeight: size.spacing[56],
        "&:last-child": {
          minHeight: "unset",
          flex: "unset",
        },
        "&:after": {
          content: "''",
          position: "absolute",
          top: size.spacing[32],
          left: `calc(${size.spacing[16]} - 1px)`,
          bottom: `-${size.spacing[4]}`,
          width: 2,
          zIndex: 0,
          backgroundColor: color.surface.componentonbackground.minimal[mode],
        },
        "&$step_complete:after": {
          backgroundColor: defaultBrandColor,
        },
        "&:last-child:after": { display: "none" },
      },
      "& $stepHeader": {
        width: "auto",
        flexDirection: "row",
        "&:after": { display: "none" },
        // add padding to focus state in vertical mode
        "&:focus-visible:before": {
          bottom: `calc(-${size.spacing[8]})`,
          top: `calc(-${size.spacing[8]})`,
          left: `calc(-${size.spacing[8]})`,
          right: `calc(-${size.spacing[8]})`,
        },
      },
      "& $stepNumber": {
        marginBottom: 0,
        marginRight: size.spacing[8],
      },
      "& $stepContent": {
        marginLeft: size.spacing[40],
      },
    },
    step: {
      flex: 1,
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      listStyle: "none",
      "&:last-child  $stepHeader:after": { display: "none" },
    },
    step_complete: {
      "& > $stepHeader": {
        color: textColor,
        "&:after": {
          backgroundColor: defaultBrandColor,
        },
      },
      "& $stepNumber": {
        color: textColor,
        border: `2px solid ${defaultBrandColor}`,
        backgroundColor: defaultBgColor,
      },
    },
    step_current: {
      "& > $stepHeader": {
        color: textColor,
        fontWeight: font.weight.bold,
      },
      "& $stepNumber": {
        backgroundColor: defaultBrandColor,
        color: color.text.neutral.minimal[mode],
      },
    },
    stepHeader: {
      extend: [focusWithPseudo({ pseudo: "before" })],
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      width: "100%",
      position: "relative",
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      whiteSpace: "nowrap",
      color: defaultTextColor,
      borderRadius: 3,
      cursor: "pointer",
      // horizontal connector
      "&:after": {
        pointerEvents: "none",
        content: "''",
        position: "absolute",
        width: "100%",
        height: 2,
        top: size.spacing[16],
        right: "-50%",
        backgroundColor: color.surface.componentonbackground.minimal[mode],
        zIndex: 0,
      },
      "&[aria-disabled='true']": {
        pointerEvents: "none",
      },
    },
    stepNumber: {
      color: color.text.neutral.strong[mode],
      width: size.spacing[32],
      height: size.spacing[32],
      lineHeight: size.spacing[32],
      borderRadius: size.spacing[32],
      backgroundColor: color.surface.componentonbackground.minimal[mode],
      fontWeight: font.weight.medium,
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      zIndex: 1,
      marginBottom: size.spacing[4],
      // icons
      "& i, & svg": {
        fontSize: size.spacing[16],
        width: size.spacing[16],
        height: size.spacing[16],
        display: "inline-flex",
        fill: "currentColor",
      },
    },
    stepContent: {
      color: textColor,
      padding: `${size.spacing[8]} 0`,
    },
    stepSubsteps: {
      padding: `${size.spacing[16]} 0`,
      paddingLeft: size.spacing[40],
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      // no need for this color, as it is overrided by stepheader color always
      // color: color.palette.coolgrey[60],
      position: "relative",
      "& $step": {
        minHeight: "unset",
        padding: size.spacing[8],
        lineHeight: size.spacing[24],
        "&:after": {
          top: "calc(-50%)",
          bottom: "50%",
          left: `calc(-${size.spacing[24]} - 1px)`,
          zIndex: 2,
        },
        "&:last-child:after": { display: "unset" },
        "&:before": {
          content: "''",
          width: size.spacing[8],
          height: size.spacing[8],
          backgroundColor: defaultBgColor,
          border: `${size.spacing[2]} solid ${defaultBgColor}`,
          borderRadius: "50%",
          boxShadow: `inset 0 0 0 1px ${color.border.neutral.strong[mode]}`,
          // boxShadow: `inset 0 0 0 1px ${color.palette.base.white}`,
          position: "absolute",
          zIndex: 3,
          top: `calc(50% - ${size.spacing[2]})`,
          left: pxToRem(-28),
        },
        "&$step_complete:before": {
          backgroundColor: defaultBrandColor,
          border: `${size.spacing[2]} solid ${defaultBgColor}`,
          //could have been none, but explicitly setting bg color to tackle increased Dark mode specificity
          boxShadow: `inset 0 0 0 1px ${defaultBrandColor}`,
        },
        "&$step_current:after": {
          backgroundColor: defaultBrandColor,
        },
        "&$step_current:before": {
          backgroundColor: defaultBrandColor,
          border: `${size.spacing[2]} solid ${defaultBrandColor}`,
          boxShadow: `inset 0 0 0 1px ${defaultBrandColor}`,
          width: size.spacing[8],
          height: size.spacing[8],
          borderRadius: "50%",
          top: `calc(50% - ${size.spacing[4]})`,
          left: pxToRem(-28),
        },
      },
    },
  };
};
